PRAGMA foreign_keys=OFF;
CREATE TABLE import_batches_v2 (id TEXT PRIMARY KEY,adapter_id TEXT NOT NULL,adapter_version TEXT NOT NULL,dataset_classification TEXT NOT NULL CHECK(dataset_classification IN ('fictional','provider-shaped-fixture','authorized-provider')),state TEXT NOT NULL CHECK(state IN ('started','completed','failed')),record_count INTEGER NOT NULL,accepted_count INTEGER NOT NULL,duplicate_count INTEGER NOT NULL,review_required_count INTEGER NOT NULL,rejected_count INTEGER NOT NULL,source_fingerprint TEXT NOT NULL UNIQUE,safe_source_snapshot_json TEXT NOT NULL,normalization_version TEXT NOT NULL,classification_version TEXT NOT NULL,validation_outcomes_json TEXT NOT NULL,failure_reason_codes_json TEXT NOT NULL,started_at_utc TEXT NOT NULL,completed_at_utc TEXT);
INSERT INTO import_batches_v2 SELECT * FROM import_batches;
CREATE TABLE imported_candidates_v2 (id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES import_batches_v2(id),source_provider_id TEXT NOT NULL,provider_record_id TEXT NOT NULL,source_fingerprint TEXT NOT NULL,source_snapshot_json TEXT NOT NULL,normalized_snapshot_json TEXT NOT NULL,lifecycle_state TEXT NOT NULL CHECK(lifecycle_state IN ('imported','normalized','review-required','eligible','rejected','suppressed','planned')),review_state TEXT NOT NULL CHECK(review_state IN ('pending','confirmed','corrected','rejected','suppressed')),created_at_utc TEXT NOT NULL,updated_at_utc TEXT NOT NULL,UNIQUE(source_provider_id,provider_record_id));
INSERT INTO imported_candidates_v2 SELECT * FROM imported_candidates;
CREATE TABLE candidate_review_audit_v2 (id INTEGER PRIMARY KEY AUTOINCREMENT,candidate_id TEXT NOT NULL REFERENCES imported_candidates_v2(id),batch_id TEXT NOT NULL REFERENCES import_batches_v2(id),action TEXT NOT NULL CHECK(action IN ('confirm','correct','reject','suppress','pending')),before_snapshot_json TEXT NOT NULL,after_snapshot_json TEXT NOT NULL,reason TEXT NOT NULL,occurred_at_utc TEXT NOT NULL);
INSERT INTO candidate_review_audit_v2 SELECT * FROM candidate_review_audit;
DROP TABLE candidate_review_audit; DROP TABLE imported_candidates; DROP TABLE import_batches;
ALTER TABLE import_batches_v2 RENAME TO import_batches; ALTER TABLE imported_candidates_v2 RENAME TO imported_candidates; ALTER TABLE candidate_review_audit_v2 RENAME TO candidate_review_audit;
CREATE INDEX imported_candidate_queue_idx ON imported_candidates(lifecycle_state,updated_at_utc);
CREATE TABLE provider_daily_budgets (provider_id TEXT NOT NULL,local_date TEXT NOT NULL,attempted_candidates INTEGER NOT NULL DEFAULT 0,estimated_max_exposure INTEGER NOT NULL DEFAULT 0,observed_consumption INTEGER,updated_at_utc TEXT NOT NULL,PRIMARY KEY(provider_id,local_date));
CREATE TABLE provider_operations (id TEXT PRIMARY KEY,provider_id TEXT NOT NULL,batch_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN ('search','enrichment')),state TEXT NOT NULL CHECK(state IN ('authorized','completed','failed')),candidate_count INTEGER NOT NULL,estimated_max_exposure INTEGER NOT NULL,observed_consumption INTEGER,attempt_count INTEGER NOT NULL DEFAULT 0,failure_reason TEXT,occurred_at_utc TEXT NOT NULL);
CREATE TRIGGER imported_candidate_planning_geography AFTER INSERT ON fictional_targeting_profiles WHEN NEW.profile_version LIKE '%import%' BEGIN UPDATE fictional_targeting_profiles SET geography_id=COALESCE((SELECT json_extract(normalized_snapshot_json,'$.geographyId') FROM imported_candidates WHERE id=NEW.prospect_id),NEW.geography_id) WHERE prospect_id=NEW.prospect_id; END;
PRAGMA foreign_keys=ON;
